        list: List.Handler,
        list_deferred: ?List.DeferredHandler = null,
        subscribe: Subscribe.Handler,
        subscribe_deferred: ?Subscribe.DeferredHandler = null,
        setWatchedKeys: SetWatchedKeys.Handler,
